def is_text(data: bytes) -> bool:
    if b'\0' in data:
        return False
    sample = data[:65536]
    if not sample:
        return True
    # Allow common whitespace controls; flag high binary-control ratio.
    controls = sum(1 for b in sample if b < 32 and b not in (9, 10, 13, 12))
    if controls / max(1, len(sample)) > 0.02:
